import{_ as o,a0 as l,w as r,s as i,ao as d,I as p,x as a,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"命令列星期二——第八部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二——第八部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二——第八部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二——第八部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20180813 Command Line Tuesdays--Part Eight","title":"命令列星期二——第八部分","tag":"201408","desc":""},"relativePath":"201408/20180813 Command Line Tuesdays--Part Eight.md","filePath":"[post].md"}'),h={name:"201408/20180813 Command Line Tuesdays--Part Eight.md"};function m(u,e,T,f,b,C){const t=l("Link");return r(),i("div",null,[e[13]||(e[13]=d(`<h1 id="命令列星期二——第八部分" tabindex="-1">命令列星期二——第八部分 <a class="header-anchor" href="#命令列星期二——第八部分" aria-label="Permalink to “命令列星期二——第八部分”">​</a></h1><p>唷，唷，極客們！我們回來了，來完成最後一章的CLT。今天，我們將討論一下任務控制。在這個裏頭，我們也將學習怎樣來控制運行在我們計算機上的進程！</p><h3 id="一個例子" tabindex="-1">一個例子 <a class="header-anchor" href="#一個例子" aria-label="Permalink to “一個例子”">​</a></h3><p>正如我們所學的，我們可以直接在CLI中輸入程序名稱來運行該程序。例如，dolphin。如果我們輸入：</p><pre><code>dolphin
</code></pre><p>……dolphin，這個文件管理器，就打開了。如果在這個進程打開時你查看終端，你會發現不能訪問命令提示符了，而且你也不能在同一個窗口中寫一個新命令進去了。如果你終止dolphin，提示符又會出現了，而你又能輸入一個新命令到shell中去了。那麼，我們怎麼能在CLI運行一個程序時，同時又能獲得提示符以便進一步發命令。</p><pre><code>dolphin &amp;
</code></pre><p>……現在你讓dolphin文件管理器在後台運行了，終端就可以空出來輸入你需要的另外一個命令了。</p><p>現在，假設你忘了在dolphin後面輸入‘&amp;’字符，你只需要輸入‘ctrl+z’，它會停止你的進程並把它放到空閒列表中去。要繼續停止的進程，輸入：</p><pre><code>bg
</code></pre><p>……它會從後台重啓進程。</p><h3 id="jobs-ps" tabindex="-1">jobs, ps <a class="header-anchor" href="#jobs-ps" aria-label="Permalink to “jobs, ps”">​</a></h3><p>由於我們在後台運行着進程，你可以使用jobs或者使用ps來列出它們。試試吧，只要輸入jobs或者輸入ps就行了。下面是我得到的結果：</p><pre><code>nenad@linux-zr04:~&gt; ps
PID TTY          TIME CMD
8356 pts/1    00:00:00 bash
8401 pts/1    00:00:00 dolphin
8406 pts/1    00:00:00 kbuildsycoca4
8456 pts/1    00:00:00 ps
</code></pre><h3 id="殺死進程" tabindex="-1">殺死進程 <a class="header-anchor" href="#殺死進程" aria-label="Permalink to “殺死進程”">​</a></h3><p>如果有個進程無響應了，怎麼來處理掉它呢？可以使用kill命令。讓我們在先前提到的dolphin進程上試試。首先，我們必須使用ps來鑑別該進程的PID。在我上述情況中，dolphin的PID是8401。那麼讓我們來殺死它，我只要輸入：</p><pre><code>kill 8401
</code></pre><p>……那麼，它就把dolphin給殺死了。</p><h3 id="kill的更多細節" tabindex="-1">kill的更多細節 <a class="header-anchor" href="#kill的更多細節" aria-label="Permalink to “kill的更多細節”">​</a></h3><p>kill的存在，不僅僅是為了終止進程，它最初是設計用來發送信號給進程。當然，有許多kill信號可以使用，根據你使用的應用程序不同而不同。請看下面的表：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/08/snapshot1.png" alt=""></p><p>務必試試這些信號。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>我們以本節課來結束我們的CLT系列和週二必達，我希望其他像我這樣的新手們能設法在他們的思想中擺脱控制台的神秘而學習掌握一些基本技能。現在對你們而言，所有剩下來要做的事，就是盡情擺弄它吧（只是別把“/”目錄搞得太亂七八糟，因而你也不會詆譭什麼東西了 😄）。</p><p>我們將在不久的將來看到其它更多的東西，因為有更多的系列文章來自這些文章的出處。別走開，同時……</p><h3 id="盡情享受" tabindex="-1">……盡情享受！ <a class="header-anchor" href="#盡情享受" aria-label="Permalink to “……盡情享受！”">​</a></h3><hr>`,27)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),n(t,{href:"https://news.opensuse.org/2014/08/12/command-line-tuesdays-part-eight/"},{default:s(()=>[...e[0]||(e[0]=[a("https://news.opensuse.org/2014/08/12/command-line-tuesdays-part-eight/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),n(t,{href:"https://news.opensuse.org/author/holden87/"},{default:s(()=>[...e[2]||(e[2]=[a("Nenad Latinović",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),n(t,{href:"https://github.com/GOLinux"},{default:s(()=>[...e[3]||(e[3]=[a("GOLinux",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const k=o(h,[["render",m]]);export{L as __pageData,k as default};
